import { expect, test } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("Pagination limits are enforced", { tag: "@VEN-06" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");

    // Act
    const res = await member.get("/api/vendors", { params: { limit: 101 } });

    // Assert
    expect(res.status(), await res.text()).toBe(422);
  });
});
